const ti = root.querySelector('#ti');
const cs = [1, 2, 3, 4, 5].map(i => root.querySelector('#c' + i));
const ls = [1, 2, 3, 4, 5].map(i => root.querySelector('#l' + i));
const len = ls.map(l => {
  const lval = l.getTotalLength();
  l.style.strokeDasharray = lval;
  l.style.strokeDashoffset = lval;
  return lval;
});

function frame(t, p, d) {
  const tf = p * d;

  const s0 = spr(tf, 0.2, 0.85, 6);
  ti.style.opacity = clamp(s0 * 1.5);
  ti.style.transform = `translateY(${lerp(20, 0, E_OUT(clamp(s0)))}px)`;

  cs.slice(0, 3).forEach((c, i) => {
    const s = spr(tf, 0.6 + i * 0.3, 0.85, 6);
    c.style.opacity = clamp(s * 1.5);
    c.style.transform = `scale(${lerp(0.9, 1, E_OUT(clamp(s)))}) translateY(${lerp(30, 0, E_OUT(clamp(s)))}px)`;
  });

  const s4 = spr(tf, 2.0, 0.85, 6);
  cs[3].style.opacity = clamp(s4 * 1.5);
  cs[3].style.transform = `translateY(${lerp(30, 0, E_OUT(clamp(s4)))}px)`;

  const s5 = spr(tf, 2.8, 0.85, 6);
  cs[4].style.opacity = clamp(s5 * 1.5);
  cs[4].style.transform = `translateY(${lerp(30, 0, E_OUT(clamp(s5)))}px)`;

  const lT = [0.4, 2.0, 2.0, 2.0, 2.8];
  ls.forEach((l, i) => {
    const s = spr(tf, lT[i], 0.9, 5);
    l.style.strokeDashoffset = lerp(len[i], 0, E_OUT(clamp(s)));
    l.style.opacity = lerp(0, 0.3, E_OUT(clamp(s)));
  });
}
